+    try {
+      view = deps.parse(text);
+    } catch (err) {
+      warnings.push(`[bridgebuilder] trusted config (${source}${ref ? ` ${ref}` : ""}) unreadable: ${err instanceof Error ? err.message : String(err)} — no provider declaration is trusted`);
