+      } catch {
+        headView = undefined;   // (an unparsable head declares nothing Bridgebuilder would admit)
+      }
+      const headWarnings: string[] = [];
+      const head = headView ? parseProviderDecls(headView.providers, "head config", headWarnings) : {};
